import {lessons,escapeHTML as esc} from './learning.js';
import {recordId} from './ids.js';
export function createTeamChallenge(root,api){
 let players=[],player=0,question=0,questions=[],answered=false,results=[];
 function scoreboard(){const rounds=api.getState().groupRounds||[];root.querySelector('#team-scoreboard').innerHTML=rounds.length?rounds.map(round=>{const sorted=[...round.entries].sort((a,b)=>b.correct-a.correct),rank=e=>sorted.findIndex(x=>x.correct===e.correct)+1;return `<div class="team-round"><span class="campus-kicker">LỚP ${round.grade} · ${new Date(round.date).toLocaleDateString('vi-VN')}</span><table><thead><tr><th>Hạng</th><th>Người tham gia</th><th>Kết quả</th></tr></thead><tbody>${sorted.map(e=>`<tr><td>${rank(e)}</td><td>${esc(e.name)}</td><td>${e.correct}/${e.total}</td></tr>`).join('')}</tbody></table></div>`}).join(''):'<p class="campus-small">Chưa có phiên nhóm. Bảng chỉ xuất hiện sau khi người tham gia thực sự trả lời trên thiết bị này.</p>'}
 function setup(){root.innerHTML=`<div class="world-section-heading"><div><span class="campus-kicker">CÙNG NHAU KIỂM CHỨNG</span><h2>Một bàn học, một thử thách chung.</h2><p>Hai đến sáu người thay phiên trên cùng thiết bị. Kết quả được tính từ lượt trả lời, không có điểm hoặc người chơi tạo sẵn.</p></div></div><div class="team-layout"><section class="campus-card"><div id="team-setup"><label for="team-names">Tên người tham gia, cách nhau bằng dấu phẩy</label><input id="team-names" maxlength="190" placeholder="Nhập tên các bạn trong nhóm"><p class="campus-small">Mỗi người làm ba câu từ khối lớp đang chọn trong học liệu. Đây là hoạt động ôn tập cùng nhau, không phải bài thi chuẩn hóa.</p><button id="team-start" class="campus-button" type="button">Bắt đầu phiên nhóm</button></div><div id="team-playing" hidden><span id="team-turn" class="campus-kicker"></span><h3 id="team-question"></h3><div id="team-answers" class="campus-answers"></div><p id="team-feedback" class="campus-small" role="status"></p><button id="team-next" class="campus-button" type="button" hidden>Tiếp tục →</button></div><p id="team-message" class="campus-small" role="status"></p></section><section class="campus-card"><span class="campus-kicker">BẢNG KẾT QUẢ NHÓM TRÊN THIẾT BỊ</span><div id="team-scoreboard"></div><p class="campus-small">Lưu tối đa 10 phiên trong trình duyệt này. Không phải xếp hạng trực tuyến hoặc dữ liệu của cả lớp ở nhiều máy; không cộng XP vào hồ sơ cá nhân của người giữ máy.</p></section></div>`;scoreboard()}
 function draw(){const q=questions[question];answered=false;root.querySelector('#team-turn').textContent=`${players[player]} · CÂU ${question+1}/${questions.length}`;root.querySelector('#team-question').textContent=q.question;root.querySelector('#team-answers').innerHTML=q.answers.map((a,i)=>`<button type="button" data-team-answer="${i}">${esc(a)}</button>`).join('');root.querySelector('#team-feedback').textContent='';root.querySelector('#team-next').hidden=true}
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='team-start'){players=[...new Set(root.querySelector('#team-names').value.split(',').map(n=>n.trim().slice(0,30)).filter(Boolean))];if(players.length<2||players.length>6){root.querySelector('#team-message').textContent='Nhập từ 2 đến 6 tên khác nhau, ngăn bằng dấu phẩy.';return}const grade=api.getState().grade;questions=lessons.filter(l=>l.grade===grade).slice(0,3);player=0;question=0;results=players.map(name=>({name,correct:0,total:questions.length}));root.querySelector('#team-setup').hidden=true;root.querySelector('#team-playing').hidden=false;root.querySelector('#team-message').textContent='';draw()}
 else if(b.dataset.teamAnswer!==undefined&&!answered){answered=true;const q=questions[question],correct=Number(b.dataset.teamAnswer)===q.correct;if(correct)results[player].correct++;api.feedback?.(b,correct);root.querySelectorAll('[data-team-answer]').forEach(b=>b.disabled=true);root.querySelector('#team-feedback').textContent=(correct?'Đúng. ':'Hãy xem lại. ')+q.explanation;root.querySelector('#team-next').hidden=false}
 else if(b.id==='team-next'&&answered){question++;if(question===questions.length){question=0;player++}if(player>=players.length){const s=api.getState();s.groupRounds.unshift({id:recordId(),grade:questions[0].grade,date:new Date().toISOString(),entries:results});s.groupRounds=s.groupRounds.slice(0,10);api.persist();root.querySelector('#team-setup').hidden=false;root.querySelector('#team-playing').hidden=true;root.querySelector('#team-message').textContent='Đã lưu phiên nhóm. Xem lại phần giải thích để cùng rút ra điều cần ôn.';scoreboard()}else draw()}});setup();
}
